#!/bin/bash
set -e
VITQA_DIR="/root/vitqa"

echo "=== Writing style.css ==="
echo "" | base64 -d > "$VITQA_DIR/frontend/css/style.css"
echo "   $(wc -c < "$VITQA_DIR/frontend/css/style.css") bytes written"

echo "=== Writing app.js ==="
echo "" | base64 -d > "$VITQA_DIR/frontend/js/app.js"  
echo "   $(wc -c < "$VITQA_DIR/frontend/js/app.js") bytes written"

echo "=== Restarting vitqa ==="
OLD_PID=$(ps aux | grep "python run.py" | grep -v grep | awk '{print $2}')
[ -n "$OLD_PID" ] && kill $OLD_PID 2>/dev/null && sleep 2
cd "$VITQA_DIR/backend" && nohup python3 run.py > /tmp/vitqa.log 2>&1 &
sleep 2
curl -s http://localhost:5005/api/health
echo "=== Done! ==="
